import XCTest
@testable import HandyTools

/// Windows help files: a .chm made with an independent compiler (Free Pascal's chmcmd) unpacks byte-for-byte the same
/// as the reference extractor (chmlib) — checked here by length and checksum — across several LZX reset points, and
/// opens as a book in its table-of-contents order with pictures beside it. A hand-built LZX stream covers the aligned
/// and stored block kinds that compiler never writes.
final class CHMTests: XCTestCase {
    private func fnv(_ d: Data) -> UInt32 { d.reduce(0x811C_9DC5 as UInt32) { ($0 ^ UInt32($1)) &* 0x0100_0193 } }
    private var chm: Data { Data(base64Encoded: Self.book, options: .ignoreUnknownCharacters)! }

    func testUnpacksLikeTheReference() throws {
        let files = try XCTUnwrap(CHMReader.files(chm))
        let expected: [(String, Int, UInt32)] = [("/a.html", 10714, 0xab5e73e5), ("/sub/b.html", 141022, 0x70ad5e44),
                                                 ("/lamp.png", 592, 0x84f08cae), ("/toc.hhc", 362, 0xab37912a)]
        for (name, length, sum) in expected {
            let d = try XCTUnwrap(files[name], name)
            XCTAssertEqual(d.count, length, name); XCTAssertEqual(fnv(d), sum, name)
        }
    }

    func testOpensAsBookInContentsOrder() throws {
        let u = FileManager.default.temporaryDirectory.appendingPathComponent("lantern.chm")
        try chm.write(to: u)
        let b = try XCTUnwrap(CHMReader.book(u))
        XCTAssertEqual(b.title, "Big Lantern Book")
        XCTAssertEqual(b.chapters.map(\.title), ["One", "Two", "Three"])
        // Pictures sit next to the pages, and each page knows its own folder.
        let dir = try XCTUnwrap(b.baseDir)
        XCTAssertTrue(FileManager.default.fileExists(atPath: dir.appendingPathComponent("lamp.png").path))
        XCTAssertTrue(b.chapters[1].html.contains("/sub/\""))
        if case .book = FileReaders.read(u) {} else { XCTFail("File Opener should show the help file as a book") }
        XCTAssertEqual(FileReaders.support("chm"), .reads)
    }

    func testAlignedAndStoredBlocks() throws {
        let stream = [UInt8](try XCTUnwrap(Data(base64Encoded: Self.mixed)))
        let out = try XCTUnwrap(LZX.decode(stream, from: 0, to: stream.count, count: 310, windowBits: 16))
        XCTAssertEqual(out.count, 310)
        XCTAssertEqual(fnv(Data(out)), 0xe4f9528d)
        XCTAssertTrue(String(decoding: out, as: UTF8.self).contains("RAW-bytes-kept-as-they-are!after the raw part"))
    }

    func testDamagedFileIsRefused() {
        var d = chm
        d.replaceSubrange(9000..<12000, with: Data(repeating: 0x5A, count: 3000))
        XCTAssertNil(CHMReader.files(Data(chm.prefix(300))))
        _ = CHMReader.files(d)   // must not crash or hang on garbage
    }

    static let book = """
